messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Red vs Blue — three.js race</title>
  <style>
    body { margin: 0; overflow: hidden; background: #000; font-family: Arial, sans-serif; }
    #info {
      position: absolute;
      top: 20px;
      left: 20px;
      color: white;
      background: rgba(0,0,0,0.6);
      padding: 10px 16px;
      border-radius: 8px;
      font-size: 18px;
      pointer-events: none;
      z-index: 10;
      letter-spacing: 1px;
      box-shadow: 0 0 15px rgba(0,0,0,0.5);
    }
    .red-text { color: #ff4d4d; font-weight: bold; }
    .blue-text { color: #4da6ff; font-weight: bold; }
  </style>
</head>
<body>
  <div id="info">
    <span class="red-text">RED</span> vs <span class="blue-text">BLUE</span> — 
    <span class="red-text">RED wins!</span> 
    <span style="opacity:0.8;">(loop)</span>
  </div>

  <script type="importmap">
    {
      "imports": {
        "three": "./three.module.js"
      }
    }
  </script>

  <script type="module">
    import * as THREE from './three.module.js';

    // --- Setup scene, camera, renderer ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // sky blue

    // Ground
    const groundGeo = new THREE.PlaneGeometry(80, 30);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x4a5a3a, roughness: 0.9 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.5;
    scene.add(ground);

    // Track markings (simple stripes)
    const stripeMat = new THREE.MeshBasicMaterial({ color: 0xcccccc });
    for (let i = -5; i <= 5; i++) {
      const stripeGeo = new THREE.PlaneGeometry(0.8, 0.15);
      const stripe = new THREE.Mesh(stripeGeo, stripeMat);
      stripe.rotation.x = -Math.PI / 2;
      stripe.position.set(i * 3, 0.01, 0);
      scene.add(stripe);
    }

    // Finish line (checkered pattern)
    const finishMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const finishBlack = new THREE.MeshBasicMaterial({ color: 0x222222 });
    const finishGroup = new THREE.Group();
    for (let r = 0; r < 3; r++) {
      for (let c = 0; c < 4; c++) {
        const tile = new THREE.Mesh(
          new THREE.PlaneGeometry(0.9, 0.9),
          (r + c) % 2 === 0 ? finishMat : finishBlack
        );
        tile.rotation.x = -Math.PI / 2;
        tile.position.set(-1.5 + c * 1.0, 0.02, -1.5 + r * 1.0);
        finishGroup.add(tile);
      }
    }
    finishGroup.position.set(30, 0, 0); // finish line at x = 30
    scene.add(finishGroup);

    // Some simple "grandstand" / distance markers
    const markerMat = new THREE.MeshStandardMaterial({ color: 0xffcc66 });
    for (let i = 0; i <= 6; i++) {
      const marker = new THREE.Mesh(new THREE.BoxGeometry(0.4, 1.2, 0.4), markerMat);
      marker.position.set(i * 6, 0.6, -4.5);
      scene.add(marker);
    }

    // Lighting
    const ambient = new THREE.AmbientLight(0x404060);
    scene.add(ambient);
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(10, 20, 10);
    scene.add(dirLight);
    const dirLight2 = new THREE.DirectionalLight(0xffd0aa, 0.6);
    dirLight2.position.set(-10, 10, -5);
    scene.add(dirLight2);

    // --- Car construction ---
    function createCar(color, isRed) {
      const group = new THREE.Group();

      // Body
      const bodyMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.4, metalness: 0.2 });
      const bodyGeo = new THREE.BoxGeometry(2.2, 0.7, 1.2);
      const body = new THREE.Mesh(bodyGeo, bodyMat);
      body.position.y = 0.35;
      group.add(body);

      // Cabin (glass)
      const cabinMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.2, metalness: 0.5 });
      const cabinGeo = new THREE.BoxGeometry(1.0, 0.5, 1.0);
      const cabin = new THREE.Mesh(cabinGeo, cabinMat);
      cabin.position.set(0.2, 0.75, 0);
      group.add(cabin);

      // Wheels (dark cylinders)
      const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.8 });
      const wheelGeo = new THREE.CylinderGeometry(0.35, 0.35, 0.25, 16);

      const wheelPositions = [
        [-0.8, 0.35, 0.65],
        [-0.8, 0.35, -0.65],
        [0.8, 0.35, 0.65],
        [0.8, 0.35, -0.65]
      ];

      wheelPositions.forEach(pos => {
        const wheel = new THREE.Mesh(wheelGeo, wheelMat);
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(pos[0], pos[1], pos[2]);
        group.add(wheel);
      });

      // Spoiler (rear)
      const spoilerMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
      const spoiler = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.1, 1.4), spoilerMat);
      spoiler.position.set(-1.2, 0.9, 0);
      group.add(spoiler);

      // Headlights (small spheres)
      const lightMat = new THREE.MeshStandardMaterial({ color: 0xffffaa, emissive: 0x444400 });
      const lightGeo = new THREE.SphereGeometry(0.12, 8, 8);
      const headL = new THREE.Mesh(lightGeo, lightMat);
      headL.position.set(1.1, 0.4, 0.5);
      group.add(headL);
      const headR = new THREE.Mesh(lightGeo, lightMat);
      headR.position.set(1.1, 0.4, -0.5);
      group.add(headR);

      // Tail lights (red for both, but glow)
      const tailMat = new THREE.MeshStandardMaterial({ color: 0xff2222, emissive: 0x550000 });
      const tailGeo = new THREE.SphereGeometry(0.1, 6, 6);
      const tailL = new THREE.Mesh(tailGeo, tailMat);
      tailL.position.set(-1.1, 0.4, 0.5);
      group.add(tailL);
      const tailR = new THREE.Mesh(tailGeo, tailMat);
      tailR.position.set(-1.1, 0.4, -0.5);
      group.add(tailR);

      return group;
    }

    // --- Create cars ---
    const redCar = createCar(0xff3333, true);
    const blueCar = createCar(0x3333ff, false);

    // Position cars: blue starts ahead, red behind
    blueCar.position.set(5, 0, 1.2);
    redCar.position.set(-2, 0, -1.2);

    scene.add(redCar);
    scene.add(blueCar);

    // --- Animation state ---
    const startX = -5;   // starting line x
    const finishX = 30;  // finish line x
    const totalDistance = finishX - startX; // 35 units

    let raceTime = 0; // seconds (scaled)
    const raceDuration = 6.0; // loop duration in seconds

    // Blue car: leads early, then slower
    // Red car: accelerates, overtakes mid-race, wins
    // We define progress functions: 0 at start, 1 at finish

    // Blue: linear-ish but slower in second half
    function blueProgress(t) {
      // t: 0..1
      // Blue leads early: fast start, then plateau
      // Use ease out: starts fast, ends slow
      return Math.min(1, t * 1.2); // reaches 1 at t=0.833, but we want finish at t=1
      // Actually let's make blue reach finish at t=1 but slower later
      // Use power curve: p = t^0.9 -> early lead
      // But we want blue to lead early, so blue should have higher p at small t
      // Let's use: p = t * (1 + 0.3 * Math.sin(t * Math.PI))? 
      // Simpler: p = Math.pow(t, 0.7) -> early lead, but finishes at same time as red?
      // We want red to overtake mid-race and win. So blue leads early, red catches up.
      // Use blue: p = t (linear) but with a "slow" later: p = t * (1 - 0.15 * t)
      // At t=0.5, p=0.5*0.925=0.4625; red at t=0.5 should be ~0.55? 
      // Let's craft: blue p = t * (1 - 0.1*t) => at t=1, p=0.9 (finish at 0.9) -> need to scale
      // Better: blue p = t * (1 - 0.2 * t) => at t=1, p=0.8, so blue finishes later than red
      // We want red to win, so blue can finish after red. Let blue p = t * (1 - 0.25 * t) => at t=1, p=0.75
      // But we want blue to lead early: at t=0.2, p=0.2*0.95=0.19; red p maybe 0.15? 
      // Let's use explicit: blue p = t * (1 - 0.15 * t) => at t=1, p=0.85
      // Red p = t * (1 + 0.15 * t) => at t=1, p=1.15 -> overshoot, clamp to 1
      // At t=0.5: blue p=0.5*0.925=0.4625; red p=0.5*1.075=0.5375 -> red ahead at mid
      // At t=0.3: blue p=0.3*0.955=0.2865; red p=0.3*1.045=0.3135 -> red already ahead? no, blue should lead early
      // So adjust: blue p = t * (1 - 0.1*t) => at t=0.3: 0.3*0.97=0.291; red p=0.3*1.1=0.33 -> red ahead
      // Need blue lead early: blue p = t * (1 - 0.05*t) => at t=0.3: 0.3*0.985=0.2955; red p=0.3*1.1=0.33 -> still red
      // Let's try blue p = t * (1 - 0.25*t) => at t=0.3: 0.3*0.925=0.2775; red p=0.3*1.15=0.345 -> red ahead
      // So need blue to have higher p at small t: use blue p = t * (1 + 0.2*t)?? That would blue lead early and also finish later? 
      // Actually blue should lead early, then red overtakes. So blue p at t=0.3 > red p at t=0.3.
      // Let's define blue p = t * (1 - 0.1*t) => at t=0.3: 0.3*0.97=0.291
      // red p = t * (1 + 0.15*t) => at t=0.3: 0.3*1.045=0.3135 -> red ahead. 
      // So we need blue p to be higher early: blue p = t * (1 + 0.05*t) => at t=0.3: 0.3*1.015=0.3045; red p=0.3*1.15=0.345? still red.
      // Let's make blue p = t * (1 + 0.2*t) => at t=0.3: 0.3*1.06=0.318; red p=0.3*1.1=0.33 -> red still slightly ahead.
      // To have blue lead early, we need blue p > red p for t < ~0.5.
      // Let's set blue p = t * (1 + 0.3*t) => at t=0.3: 0.3*1.09=0.327; red p=0.3*1.1=0.33 -> still red ahead.
      // Hmm, red needs to start slower, then accelerate. So red p should be lower early.
      // Let's define red p = t * (1 - 0.1*t) => at t=0.3: 0.3*0.97=0.291; blue p = t * (1 + 0.1*t) => at t=0.3: 0.3*1.03=0.309 -> blue ahead. 
      // At t=0.5: blue p=0.5*1.05=0.525; red p=0.5*0.95=0.475 -> blue ahead. 
      // At t=0.7: blue p=0.7*1.07=0.749; red p=0.7*0.93=0.651 -> blue ahead. 
      // Need red overtakes mid-race. So red should accelerate more later.
      // Let's use red p = t * (1 + 0.15*t) => at t=0.3: 0.3*1.045=0.3135; blue p=0.3*1.1=0.33 -> blue ahead.
      // At t=0.5: red p=0.5*1.075=0.5375; blue p=0.5*1.1=0.55 -> blue still ahead.
      // At t=0.7: red p=0.7*1.105=0.7735; blue p=0.7*1.1=0.77 -> red slightly ahead! Good.
      // At t=0.9: red p=0.9*1.135=1.0215 -> clamp to 1; blue p=0.9*1.1=0.99 -> red wins.
      // At t=1: red p=1.15 -> clamp to 1; blue p=1.1 -> clamp to 1? but blue should finish after red.
      // Actually if both clamp to 1, they tie at finish. We want red to cross first.
      // Let's make blue p = t * (1 + 0.1*t) but cap at 0.95? 
      // Simpler: use two separate progress functions with different rates.

      // I'll define:
      // blue: p = t * (1 + 0.1 * t) but clamp to 0.98 (so blue never quite reaches 1 before red)
      // red: p = t * (1 + 0.15 * t) clamp to 1.0
      // At t=0.3: blue=0.3*1.03=0.309; red=0.3*1.045=0.3135 -> red slightly ahead? no, blue 0.309 < red 0.3135 -> red ahead early, bad.
      // Need blue lead early. So blue should have higher p at small t.
      // Let's use blue p = t * (1 + 0.2*t) => at t=0.3: 0.3*1.06=0.318; red p=0.3*1.1=0.33 -> red still ahead.
      // Hmm, red needs to be slower early. So red p = t * (1 - 0.1*t) => at t=0.3: 0.3*0.97=0.291; blue p=0.3*1.2=0.36 -> blue ahead.
      // At t=0.5: blue p=0.5*1.2=0.6; red p=0.5*0.95=0.475 -> blue ahead.
      // At t=0.7: blue p=0.7*1.2=0.84; red p=0.7*0.93=0.651 -> blue ahead.
      // At t=0.9: blue p=0.9*1.2=1.08 -> clamp to 1.0; red p=0.9*0.91=0.819 -> red behind.
      // This makes blue win, not what we want.

      // Let's use asymmetric: blue leads early, but red accelerates strongly later.
      // blue p = t * (1 + 0.1*t) => at t=0.3: 0.3*1.03=0.309; red p = t * (1 - 0.1*t) => 0.3*0.97=0.291 -> blue ahead.
      // At t=0.5: blue=0.5*1.05=0.525; red=0.5*0.95=0.475 -> blue ahead.
      // At t=0.7: blue=0.7*1.07=0.749; red=0.7*0.93=0.651 -> blue ahead.
      // At t=0.9: blue=0.9*1.09=0.981; red=0.9*0.91=0.819 -> blue ahead.
      // So blue always ahead. Need red to overtake. So red must have a burst later.
      // Let's make red p = t * (1 + 0.25*t) => at t=0.3: 0.3*1.075=0.3225; blue=0.309 -> red slightly ahead, bad.
      // At t=0.2: red=0.2*1.05=0.21; blue=0.2*1.02=0.204 -> red ahead.
      // So need blue to start faster. Let's set blue p = t * (1 + 0.3*t) => at t=0.2: 0.2*1.06=0.212; red=0.2*1.0=0.2 -> blue ahead.
      // At t=0.5: blue=0.5*1.15=0.575; red=0.5*1.125=0.5625 -> blue ahead.
      // At t=0.7: blue=0.7*1.21=0.847; red=0.7*1.175=0.8225 -> blue ahead.
      // At t=0.9: blue=0.9*1.27=1.143 -> clamp to 1; red=0.9*1.225=1.1025 -> clamp to 1, tie.
      // Need red to win, so red must have higher final speed. 

      // Let's use different approach: blue p = t (linear), red p = t^1.5 (slow early, fast late)
      // At t=0.3: blue=0.3; red=0.3^1.5=0.164 -> blue ahead.
      // At t=0.5: blue=0.5; red=0.5^1.5=0.354 -> blue ahead.
      // At t=0.7: blue=0.7; red=0.7^1.5=0.586 -> blue ahead.
      // At t=0.9: blue=0.9; red=0.9^1.5=0.854 -> blue ahead.
      // At t=1.0: blue=1.0; red=1.0 -> tie. 
      // Need red to overtake before finish. So red p should cross blue p before t=1.
      // Use red p = t^2 (quadratic): at t=0.3: 0.09; blue=0.3 -> blue ahead.
      // at t=0.5: red=0.25; blue=0.5 -> blue.
      // at t=0.7: red=0.49; blue=0.7 -> blue.
      // at t=0.9: red=0.81; blue=0.9 -> blue.
      // at t=1: tie. 
      // Use red p = t^3: at t=0.9: 0.729; blue=0.9 -> blue.
      // So red always behind.

      // To have red overtake, red must have a steeper curve that crosses blue before t=1.
      // Let blue p = t (linear), red p = 0.2 + 0.8*t^2? at t=0.3: 0.2+0.8*0.09=0.272; blue=0.3 -> blue ahead.
      // at t=0.5: red=0.2+0.8*0.25=0.4; blue=0.5 -> blue.
      // at t=0.7: red=0.2+0.8*0.49=0.592; blue=0.7 -> blue.
      // at t=0.9: red=0.2+0.8*0.81=0.848; blue=0.9 -> blue.
      // at t=1: red=1.0; blue=1.0 tie.
      // Need red to be ahead at some point before 1. 
      // Let blue p = t * (1 - 0.1*t) => at t=0.9: 0.9*0.91=0.819; red p = t * (1 + 0.1*t) => 0.9*1.09=0.981 -> red ahead at 0.9. 
      // At t=0.5: blue=0.5*0.95=0.475; red=0.5*1.05=0.525 -> red ahead already at 0.5. 
      // At t=0.3: blue=0.3*0.97=0.291; red=0.3*1.03=0.309 -> red ahead. 
      // So blue never leads. Need blue lead early. 

      // Let's craft piecewise: blue leads until t=0.4, then red accelerates.
      // Use simple: blue p = t (linear), red p = t * (1 + 0.3 * Math.max(0, t - 0.4) / 0.6) 
      // At t=0.3: red=0.3*1=0.3; blue=0.3 -> tie.
      // At t=0.2: red=0.2; blue=0.2 tie.
      // At t=0.5: red=0.5*(1+0.3*0.1/0.6)=0.5*1.05=0.525; blue=0.5 -> red ahead.
      // At t=0.7: red=0.7*(1+0.3*0.3/0.6)=0.7*1.15=0.805; blue=0.7 -> red ahead.
      // At t=0.9: red=0.9*(1+0.3*0.5/0.6)=0.9*1.25=1.125 -> clamp to 1; blue=0.9 -> red wins.
      // At t=0.3: red=0.3, blue=0.3 tie, but blue should lead early. 
      // Make blue p = t * (1 + 0.1*t) => at t=0.3: 0.309; red=0.3 -> blue ahead.
      // At t=0.5: blue=0.525; red=0.525 -> tie at 0.5? 
      // At t=0.7: blue=0.749; red=0.805 -> red ahead. 
      // At t=0.9: blue=0.981; red=1.125 -> red wins. 
      // At t=0.2: blue=0.2*1.02=0.204; red=0.2 -> blue ahead. 
      // Good! Blue leads early, red overtakes around t=0.6. 

      // Let's implement:
      // blueProgress(t) = t * (1 + 0.1 * t)  // max 1.1 at t=1, clamp to 1
      // redProgress(t) = t * (1 + 0.3 * Math.max(0, t - 0.4) / 0.6)  // at t=0.4: 0.4, at t=1: 1.3 -> clamp to 1
      // But at t=0.4: red=0.4, blue=0.4*1.04=0.416 -> blue ahead.
      // At t=0.5: red=0.5*(1+0.3*0.1/0.6)=0.5*1.05=0.525; blue=0.5*1.05=0.525 -> tie.
      // At t=0.6: red=0.6*(1+0.3*0.2/0.6)=0.6*1.1=0.66; blue=0.6*1.06=0.636 -> red ahead.
      // Good. So red overtakes around 0.55.

      // Let's use these functions.

      // We'll compute positions based on progress.
      // x = startX + progress * totalDistance
      // z: red stays at -1.2, blue at 1.2 (lanes)

      return {
        blue: (t) => {
          const p = t * (1 + 0.1 * t);
          return Math.min(1, p);
        },
        red: (t) => {
          const p = t * (1 + 0.3 * Math.max(0, t - 0.4) / 0.6);
          return Math.min(1, p);
        }
      };
    }

    // Actually we need to define progress functions globally
    const blueProgressFn = (t) => {
      const p = t * (1 + 0.1 * t);
      return Math.min(1, p);
    };
    const redProgressFn = (t) => {
      const p = t * (1 + 0.3 * Math.max(0, t - 0.4) / 0.6);
      return Math.min(1, p);
    };

    // --- Animation loop ---
    const clock = new THREE.Clock();
    let animTime = 0; // in seconds, loops

    function animate() {
      const delta = clock.getDelta();
      animTime += delta;

      // Loop duration 6 seconds
      const loopDuration = 6.0;
      const t = (animTime % loopDuration) / loopDuration; // 0..1

      // Compute progress
      const blueProg = blueProgressFn(t);
      const redProg = redProgressFn(t);

      // Update car positions
      const startX = -5;
      const finishX = 30;
      const totalDist = finishX - startX;

      const blueX = startX + blueProg * totalDist;
      const redX = startX + redProg * totalDist;

      blueCar.position.x = blueX;
      redCar.position.x = redX;

      // Keep cars in lanes
      blueCar.position.z = 1.2;
      redCar.position.z = -1.2;

      // Slight tilt for drama
      redCar.rotation.y = 0;
      blueCar.rotation.y = 0;

      // Camera: keep both cars in view, positioned behind and above
      const cameraTargetX = (blueX + redX) / 2;
      const cameraX = cameraTargetX * 0.5 + 5; // camera follows with some lag
      camera.position.set(cameraX, 6, 12);
      camera.lookAt(cameraTargetX, 0.5, 0);

      // Render
      renderer.render(scene, camera);

      requestAnimationFrame(animate);
    }

    // --- Camera setup ---
    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
    camera.position.set(5, 6, 12);
    camera.lookAt(5, 0.5, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = false; // keep simple
    document.body.appendChild(renderer.domElement);

    // Handle resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Start animation
    animate();

    // Small extra: add floating dust? no need.
  </script>
</body>
</html>
```
